def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    denominator = 1 + v2 / 100
    if denominator == 0:
        return None
    result = v1 / denominator
    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "denominator": denominator,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": "monetary"
            }
        }
    }
